    const n = big ? 500 : r.int(1, 7), p = big ? 0.8 : r.pick([0.2, 0.4, 0.7]);
    const rank = r.shuffle([...Array(n).keys()]);
    const richer = [];
    for (let i = 0; i < n; i++)
      for (let j = i + 1; j < n; j++)
        if (r.bool(p)) richer.push([rank[i], rank[j]]);
    return [r.shuffle(richer), r.shuffle([...Array(n).keys()])];
