function quietestRicher(richer: number[][], quiet: number[]): number[] {
  const n = quiet.length;
  const up: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of richer) up[b].push(a);
  const ans: number[] = [];
  for (let x = 0; x < n; x++) {
    const seen = new Array(n).fill(false);
    const queue = [x];
    seen[x] = true;
    let best = x;
    for (let i = 0; i < queue.length; i++) {
      const v = queue[i];
      if (quiet[v] < quiet[best]) best = v;
      for (const w of up[v]) if (!seen[w]) { seen[w] = true; queue.push(w); }
    }
    ans.push(best);
  }
  return ans;
}

