function quietestRicher(richer: number[][], quiet: number[]): number[] {
  const n = quiet.length;
  const up: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of richer) up[b].push(a);
  const ans = new Array(n).fill(-1);
  const solve = (x: number): number => {
    if (ans[x] !== -1) return ans[x];
    let best = x;
    for (const y of up[x]) {
      const c = solve(y);
      if (quiet[c] < quiet[best]) best = c;
    }
    return (ans[x] = best);
  };
  for (let x = 0; x < n; x++) solve(x);
  return ans;
}

